<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class SocialSupportController extends Controller{
 private function staff(Request $r){$u=$r->user();return $u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('upbringing_head')||$u->hasRole('social_teacher');}
 private function curatorGroups(Request $r){$u=$r->user();return $u->teacher_id?DB::table('study_groups')->where('curator_teacher_id',$u->teacher_id)->where('active',1)->pluck('id'):collect();}
 private function ok(Request $r){abort_unless($this->staff($r)||$this->curatorGroups($r)->isNotEmpty(),403);}
 private function canStudent(Request $r,$student){if($this->staff($r))return;$groups=$this->curatorGroups($r);abort_unless(DB::table('students')->where('id',$student)->whereIn('current_group_id',$groups)->exists(),403);}
 public function index(Request $r){$this->ok($r);$q=DB::table('student_social_statuses as ss')->join('students as s','s.id','=','ss.student_id')->join('student_social_categories as c','c.id','=','ss.category_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('ss.*','s.last_name','s.first_name','s.middle_name','g.name as group_name','c.name as category_name','c.code as category_code');if(!$this->staff($r))$q->whereIn('s.current_group_id',$this->curatorGroups($r));if($r->filled('group'))$q->where('s.current_group_id',$r->integer('group'));if($r->filled('category'))$q->where('ss.category_id',$r->integer('category'));if($r->filled('state'))$q->where('ss.status',$r->state);$rows=$q->orderBy('s.last_name')->get();return view('upbringing.social-statuses',['rows'=>$rows,'students'=>DB::table('students')->where('status','active')->when(!$this->staff($r),fn($q)=>$q->whereIn('current_group_id',$this->curatorGroups($r)))->orderBy('last_name')->get(),'groups'=>DB::table('study_groups')->where('active',1)->when(!$this->staff($r),fn($q)=>$q->whereIn('id',$this->curatorGroups($r)))->orderBy('name')->get(),'categories'=>DB::table('student_social_categories')->where('active',1)->orderBy('name')->get()]);}
 public function passport(Request $r,$student){$this->ok($r);$this->canStudent($r,$student);$s=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('s.id',$student)->select('s.*','g.name as group_name')->first();abort_unless($s,404);$passport=DB::table('student_social_passports')->where('student_id',$student)->first();$statuses=DB::table('student_social_statuses as ss')->join('student_social_categories as c','c.id','=','ss.category_id')->where('ss.student_id',$student)->select('ss.*','c.name as category_name')->orderByDesc('ss.id')->get();$representatives=DB::table('student_representatives')->where('student_id',$student)->get();$supports=DB::table('student_social_supports')->where('student_id',$student)->orderByDesc('id')->get();$followups=DB::table('student_social_followups')->where('student_id',$student)->orderByDesc('id')->get();return view('upbringing.social-passport',compact('s','passport','statuses','representatives','supports','followups'));}
 public function passportUpdate(Request $r,$student){$this->ok($r);$this->canStudent($r,$student);$d=$r->validate(['family_status'=>'nullable|string|max:100','family_members'=>'nullable|integer|min:0|max:50','children_in_family'=>'nullable|integer|min:0|max:30','housing_status'=>'nullable|string|max:150','guardian_name'=>'nullable|string|max:255','guardian_phone'=>'nullable|string|max:80','social_notes'=>'nullable|string|max:5000']);foreach(['dormitory','low_income','large_family','orphan','guardianship','disabled','ovz','risk_group'] as $k)$d[$k]=$r->boolean($k);$d['updated_by']=$r->user()->id;$d['updated_at']=now();DB::table('student_social_passports')->updateOrInsert(['student_id'=>$student],$d+['created_at'=>now()]);return back()->with('success','Социальный паспорт сохранён');}
 public function supportStore(Request $r,$student){$this->ok($r);$this->canStudent($r,$student);$d=$r->validate(['support_type'=>'required|string|max:120','basis'=>'nullable|string|max:255','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on','note'=>'nullable|string|max:3000']);DB::table('student_social_supports')->insert($d+['student_id'=>$student,'status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Мера поддержки добавлена');}
 public function supportDelete(Request $r,$id){$row=DB::table('student_social_supports')->find($id);abort_unless($row,404);$this->ok($r);$this->canStudent($r,$row->student_id);DB::table('student_social_supports')->where('id',$id)->delete();return back()->with('success','Мера поддержки удалена');}
 public function followupStore(Request $r,$student){$this->ok($r);$this->canStudent($r,$student);$d=$r->validate(['started_on'=>'required|date','reason'=>'required|string|max:500','responsible'=>'nullable|string|max:255','actions'=>'nullable|string|max:5000']);DB::table('student_social_followups')->insert($d+['student_id'=>$student,'status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Сопровождение открыто');}
 public function followupClose(Request $r,$id){$row=DB::table('student_social_followups')->find($id);abort_unless($row,404);$this->ok($r);$this->canStudent($r,$row->student_id);$d=$r->validate(['ended_on'=>'required|date','result'=>'nullable|string|max:5000']);DB::table('student_social_followups')->where('id',$id)->update($d+['status'=>'closed','updated_at'=>now()]);return back()->with('success','Сопровождение закрыто');}
 public function groupPassport(Request $r,$group){$this->ok($r);$u=$r->user();if(!$this->staff($r))abort_unless($this->curatorGroups($r)->contains((int)$group),403);$g=DB::table('study_groups')->find($group);abort_unless($g,404);$students=DB::table('students')->where('current_group_id',$group)->where('status','active')->get();$ids=$students->pluck('id');$p=DB::table('student_social_passports')->whereIn('student_id',$ids);$summary=['students'=>$students->count(),'dormitory'=>(clone $p)->where('dormitory',1)->count(),'low_income'=>(clone $p)->where('low_income',1)->count(),'large_family'=>(clone $p)->where('large_family',1)->count(),'orphan'=>(clone $p)->where('orphan',1)->count(),'guardianship'=>(clone $p)->where('guardianship',1)->count(),'disabled'=>(clone $p)->where('disabled',1)->count(),'ovz'=>(clone $p)->where('ovz',1)->count(),'risk_group'=>(clone $p)->where('risk_group',1)->count(),'support'=>(DB::table('student_social_supports')->whereIn('student_id',$ids)->where('status','active')->distinct()->count('student_id')),'followup'=>(DB::table('student_social_followups')->whereIn('student_id',$ids)->where('status','active')->distinct()->count('student_id'))];return view('upbringing.social-group-passport',compact('g','students','summary'));}
 public function category(Request $r){abort_unless($this->staff($r),403);$d=$r->validate(['code'=>'required|string|max:80|unique:student_social_categories,code','name'=>'required|string|max:255','note'=>'nullable|string|max:3000']);DB::table('student_social_categories')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Социальная категория добавлена');}
 public function store(Request $r){$this->ok($r);$d=$r->validate(['student_id'=>'required|exists:students,id','category_id'=>'required|exists:student_social_categories,id','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from','document_type'=>'nullable|string|max:150','document_number'=>'nullable|string|max:150','document_date'=>'nullable|date','issuer'=>'nullable|string|max:255','note'=>'nullable|string|max:5000']);$this->canStudent($r,$d['student_id']);DB::table('student_social_statuses')->insert($d+['status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Социальный статус зарегистрирован');}
 public function close(Request $r,$id){$this->ok($r);$row=DB::table('student_social_statuses')->where('id',$id)->first();abort_unless($row,404);$this->canStudent($r,$row->student_id);DB::table('student_social_statuses')->where('id',$id)->update(['status'=>'closed','valid_until'=>$r->input('valid_until',today()),'updated_at'=>now()]);return back()->with('success','Социальный статус закрыт');}
}